package com.flippingfriend.companion;
import org.junit.Test; import static org.junit.Assert.*;
public class BuyReplacementQuantityGridComposerTest {
 @Test public void appliesProductionRoundClampAndAdjacentDuplicateSuppression(){BuyReplacementKellyFractionEvaluationSet s=source();BuyReplacementQuantityGridCandidateSet r=new BuyReplacementQuantityGridComposer().compose(s,1100);assertNotNull(r);double[] grid=s.getSizeGrid();int cursor=0;for(BuyReplacementKellyFractionEvaluation e:s.getEvaluations()){int last=0;for(int j=0;j<grid.length;j++){int q=(int)Math.max(1,Math.min(e.getFillableQuantity(),Math.round(e.getFillableQuantity()*e.getKellyFraction()*grid[j])));if(q==last)continue;last=q;BuyReplacementQuantityGridCandidate c=r.getCandidates().get(cursor++);assertEquals(j,c.getSizeGridIndex());assertEquals(grid[j],c.getSizeShare(),0.0);assertEquals(q,c.getQuantity());assertTrue(q>=1&&q<=e.getFillableQuantity());}}assertEquals(cursor,r.getCandidates().size());try{r.getCandidates().clear();fail("immutable");}catch(UnsupportedOperationException expected){}}
 @Test public void unavailableAndStaleInputsFailClosed(){BuyReplacementQuantityGridComposer c=new BuyReplacementQuantityGridComposer();assertNull(c.compose(null,1100));assertNull(c.compose(source(),1221));}
 @Test public void contractsCarryNoFillEconomicsScoringSelectionOrAuthorization()throws Exception{for(String f:new String[]{"BuyReplacementQuantityGridCandidate.java","BuyReplacementQuantityGridCandidateSet.java"}){String x=java.nio.file.Files.readString(java.nio.file.Path.of("src/main/java/com/flippingfriend/companion/"+f));for(String forbidden:new String[]{"FillModel","FillEstimate","expectedGpPerSlotHour","selected","score","rank","PortfolioCandidate","PolicyDecision","OfferLifecycleAction","REPLACEMENT_AUTHORIZED"})assertFalse(x.contains(forbidden));}}
 static BuyReplacementQuantityGridCandidateSet candidateSetForCompanionTests(){return new BuyReplacementQuantityGridComposer().compose(source(),1100);} private static BuyReplacementKellyFractionEvaluationSet source(){return BuyReplacementKellyFractionEvaluatorTest.quantityGridEvaluationSetForCompanionTests();}
}
